pub fn dump_Glyph(out: &mut impl Write, path: &str, value: &Glyph<'_>) -> io::Result<()> {
    let dump_args = crate::dump_support::arguments();
    if !crate::dump_support::enter(path) {
        return writeln!(out, "{path}=traversal-limit");
    }
    match value {
        Glyph::Simple(table) => {
            writeln!(out, "{path}.kind=Simple")?;
            dump_SimpleGlyph(out, path, table)?;
        }
        Glyph::Composite(table) => {
            writeln!(out, "{path}.kind=Composite")?;
            dump_CompositeGlyph(out, path, table)?;
        }
    }
    Ok(())
}

